def transform(grid):
    target = 3
    rows = len(grid)
    cols = len(grid[0])

    if rows == 0 or cols == 0: return grid

    # Determine Horizontal Period W
    W = 1
    for w in range(1, cols + 1):
        consistent = True
        for r in range(rows):
            for c in range(cols - w):
                val1 = grid[r][c]
                val2 = grid[r][c+w]
                if val1 != target and val2 != target:
                    if val1 != val2:
                        consistent = False
                        break
            if not consistent:
                break
        if consistent:
            W = w
            break
    else: W = 1 # Should not happen for ARC

    # Determine Vertical Period H
    H = 1
    for h in range(1, rows + 1):
        consistent = True
        for c in range(cols):
            for r in range(rows - h):
                val1 = grid[r][c]
                val2 = grid[r+h][c]
                if val1 != target and val2 != target:
                    if val1 != val2:
                        consistent = False
                        break
            if not consistent:
                break
        if consistent:
            H = h
            break
    else: H = 1

    # Construct Pattern P
    P = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != target:
                key = (r % H, c % W)
                if key not in P:
                    P[key] = val

    # Generate Output
    output = []
    for r in range(rows):
        row_out = []
        for c in range(cols):
            if grid[r][c] == target:
                key = (r % H, c % W)
                row_out.append(P.get(key, target))
            else:
                row_out.append(grid[r][c])
        output.append(row_out)
    return output
